#!/usr/bin/env python3
"""
Launch file for Cartesian GUI with MoveIt Bridge
"""

from launch import LaunchDescription
from launch_ros.actions import Node
from launch.actions import DeclareLaunchArgument, IncludeLaunchDescription
from launch.substitutions import LaunchConfiguration, PathJoinSubstitution
from launch_ros.substitutions import FindPackageShare
from launch.launch_description_sources import PythonLaunchDescriptionSource


def generate_launch_description():

    # Declare arguments
    use_sim_time = LaunchConfiguration('use_sim_time', default='false')

    # Include the main MoveIt launch file
    moveit_launch = IncludeLaunchDescription(
        PythonLaunchDescriptionSource([
            PathJoinSubstitution([
                FindPackageShare('pl25488'),
                'launch',
                'demo.launch.py'
            ])
        ]),
        launch_arguments={
            'use_sim_time': use_sim_time,
        }.items()
    )

    # MoveIt GUI Bridge Node
    gui_bridge_node = Node(
        package='pl25488',
        executable='gui_bridge.py',
        name='moveit_gui_bridge',
        output='screen',
        parameters=[
            {'use_sim_time': use_sim_time}
        ]
    )

    # Cartesian GUI Node
    cartesian_gui_node = Node(
        package='pl25488',
        executable='cartesian_gui.py',
        name='cartesian_gui',
        output='screen',
        parameters=[
            {'use_sim_time': use_sim_time}
        ]
    )

    return LaunchDescription([
        DeclareLaunchArgument(
            'use_sim_time',
            default_value='false',
            description='Use simulation time'
        ),
        moveit_launch,
        gui_bridge_node,
        cartesian_gui_node,
    ])

from launch import LaunchDescription
from launch_ros.actions import Node

def generate_launch_description():
    return LaunchDescription([
        Node(
            package='pl25488',
            executable='gui_bridge.py',
            name='gui_bridge',
            output='screen'
        )
    ])
